-- Mostra CineAstra: locais de exibição, salas, assentos e modelos 3D.
-- Execute com o cliente MySQL sem --force e com a migração 71 aplicada.
-- Em seguida, aplique 02_programacao_250_filmes.sql para agendar os filmes do catálogo.
SET NAMES utf8mb4;
SET SESSION time_zone = '+00:00';

CREATE TEMPORARY TABLE mostra_local_config (
    slug VARCHAR(180) PRIMARY KEY, nome VARCHAR(150), tipo VARCHAR(25),
    cidade VARCHAR(100), bairro VARCHAR(100), logradouro VARCHAR(150), numero VARCHAR(20),
    sala VARCHAR(100), formato VARCHAR(5), capacidade INT
);
CREATE TEMPORARY TABLE mostra_local_lugares (
    slug VARCHAR(180), fileira VARCHAR(5), numero INT, tipo VARCHAR(10), posicao INT,
    PRIMARY KEY (slug, fileira, numero)
);
CREATE TEMPORARY TABLE mostra_local_cenas (
    slug VARCHAR(180) PRIMARY KEY, cabecalho JSON NOT NULL, objetos JSON NOT NULL
);
CREATE TEMPORARY TABLE mostra_local_validacao (
    regra VARCHAR(100) PRIMARY KEY, satisfeita BOOLEAN NOT NULL,
    CONSTRAINT chk_mostra_local_valida CHECK (satisfeita = TRUE)
);




START TRANSACTION;

SELECT c.slug,c.nome,c.tipo,c.cidade,'SP',c.bairro,c.logradouro,c.numero,'ATIVO',c.capacidade,'NUMERADO'
FROM mostra_local_config c LEFT JOIN locais l ON l.slug=c.slug
WHERE l.id_local IS NULL;

SELECT l.id_local,c.sala,c.capacidade,c.formato,'ATIVA'
FROM mostra_local_config c JOIN locais l ON l.slug=c.slug
LEFT JOIN salas s ON s.id_local=l.id_local AND s.nome=c.sala
WHERE s.id_sala IS NULL;

SELECT 'Tipos, capacidade e formato dos locais da mostra', COUNT(*)=11
FROM mostra_local_config c JOIN locais l ON l.slug=c.slug AND l.tipo_local=c.tipo
JOIN salas s ON s.id_local=l.id_local AND s.nome=c.sala AND s.capacidade=c.capacidade AND s.tipo=c.formato;

SELECT s.id_sala,p.fileira,p.numero,p.tipo,'ATIVA',p.posicao
FROM mostra_local_lugares p JOIN mostra_local_config c ON c.slug=p.slug
JOIN locais l ON l.slug=c.slug JOIN salas s ON s.id_local=l.id_local AND s.nome=c.sala
LEFT JOIN assentos a ON a.id_sala=s.id_sala AND a.fileira=p.fileira AND a.numero=p.numero
WHERE a.id_assento IS NULL AND s.cena_3d IS NULL;

CREATE TEMPORARY TABLE mostra_local_cenas_publicadas AS
SELECT s.id_sala, JSON_SET(c.cabecalho, '$.objects', JSON_ARRAYAGG(
    CASE WHEN o.fileira IS NULL THEN o.objeto
         ELSE JSON_SET(JSON_REMOVE(o.objeto,'$.fileira','$.numero'),'$.seatId',CAST(a.id_assento AS CHAR))
    END
)) AS cena,
SUM(a.id_assento IS NOT NULL) AS vinculados,
(SELECT COUNT(*) FROM assentos aa WHERE aa.id_sala=s.id_sala AND aa.status='ATIVA') AS ativos,
s.capacidade
FROM mostra_local_cenas c JOIN mostra_local_config p ON p.slug=c.slug
JOIN locais l ON l.slug=c.slug JOIN salas s ON s.id_local=l.id_local AND s.nome=p.sala
JOIN JSON_TABLE(c.objetos,'$[*]' COLUMNS (
    objeto JSON PATH '$', fileira VARCHAR(5) PATH '$.fileira', numero INT PATH '$.numero'
)) o
LEFT JOIN assentos a ON a.id_sala=s.id_sala AND a.fileira=o.fileira AND a.numero=o.numero AND a.status='ATIVA'
WHERE s.cena_3d IS NULL
GROUP BY s.id_sala,c.cabecalho,s.capacidade;

SELECT 'Todos os assentos ativos têm objeto 3D correspondente', NOT EXISTS (
    SELECT 1 FROM mostra_local_cenas_publicadas WHERE ativos<>vinculados OR ativos<>capacidade
);

UPDATE salas s JOIN mostra_local_cenas_publicadas c ON c.id_sala=s.id_sala
SET s.cena_3d=c.cena
WHERE s.cena_3d IS NULL;

COMMIT;

SELECT l.nome, s.nome AS sala, s.capacidade
FROM mostra_local_config c JOIN locais l ON l.slug=c.slug
JOIN salas s ON s.id_local=l.id_local AND s.nome=c.sala ORDER BY l.nome;

DROP TEMPORARY TABLE mostra_local_cenas_publicadas, mostra_local_validacao,
    mostra_local_cenas, mostra_local_lugares, mostra_local_config;